-- Generated by zetaris_setup.py. Statements are separated by ';' lines.

CREATE NAMESPACE IF NOT EXISTS lightning.metastore
;

CREATE NAMESPACE IF NOT EXISTS lightning.metastore.dd
;

COMPILE USL IF NOT EXISTS dd_usl DEPLOY NAMESPACE lightning.metastore.dd DDL
CREATE TABLE sic_code (
    sic_code varchar(4) NOT NULL PRIMARY KEY,
    description varchar(200),
    division_desc varchar(200),
    major_group_desc varchar(200),
    industry_group_desc varchar(200)
);

CREATE TABLE company (
    cik varchar(10) NOT NULL PRIMARY KEY,
    entity_name varchar(200) NOT NULL,
    ticker varchar(10),
    sic varchar(4) NOT NULL FOREIGN KEY REFERENCES sic_code(sic_code),
    sic_description_edgar varchar(200),
    state_of_incorporation varchar(10),
    fiscal_year_end varchar(4)
);

CREATE TABLE financial_fact (
    cik varchar(10) NOT NULL FOREIGN KEY REFERENCES company(cik),
    metric varchar(40) NOT NULL,
    concept varchar(120),
    fiscal_year int,
    fiscal_period varchar(4),
    period_start varchar(10),
    period_end varchar(10) NOT NULL,
    value_usd double,
    form varchar(12),
    filed varchar(10),
    accession varchar(25)
)
;

UPDATE USL lightning.metastore.dd.dd_usl SET DESCRIPTION 'Due-diligence semantic layer: SEC EDGAR financial facts and company profiles joined to the SIC industry hierarchy. One model the agent queries instead of three raw APIs.'
;

ACTIVATE USL TABLE lightning.metastore.dd.dd_usl.sic_code AS
SELECT sic_code, sic_val.description AS description, sic_val.division_desc AS division_desc,
       sic_val.major_group_desc AS major_group_desc, sic_val.industry_group_desc AS industry_group_desc
FROM company_dns.sic_codes_raw
LATERAL VIEW explode(
    from_json(to_json(data.sics), 'map<string, struct<description:string, division:string, division_desc:string, major_group:string, major_group_desc:string, industry_group:string, industry_group_desc:string>>')
) AS sic_code, sic_val
;

ACTIVATE USL TABLE lightning.metastore.dd.dd_usl.company AS
SELECT * FROM (
    SELECT COALESCE(cik, '') AS cik, COALESCE(name, '') AS entity_name, tickers[0] AS ticker, COALESCE(sic, '') AS sic, `sicDescription` AS sic_description_edgar,
           `stateOfIncorporation` AS state_of_incorporation, `fiscalYearEnd` AS fiscal_year_end
    FROM sec_profiles.rivian_submissions_raw
    UNION ALL
    SELECT COALESCE(cik, '') AS cik, COALESCE(name, '') AS entity_name, tickers[0] AS ticker, COALESCE(sic, '') AS sic, `sicDescription` AS sic_description_edgar,
           `stateOfIncorporation` AS state_of_incorporation, `fiscalYearEnd` AS fiscal_year_end
    FROM sec_profiles.lucid_submissions_raw
) AS companies
;

ACTIVATE USL TABLE lightning.metastore.dd.dd_usl.financial_fact AS
SELECT * FROM (
    SELECT '0001874178' AS cik, 'revenue' AS metric, tag AS concept, CAST(f.fy AS INT) AS fiscal_year,
           f.fp AS fiscal_period, f.`start` AS period_start, COALESCE(f.`end`, '') AS period_end,
           CAST(f.val AS DOUBLE) AS value_usd, f.form AS form, f.filed AS filed, f.accn AS accession
    FROM sec_data.rivian_revenue_raw LATERAL VIEW explode(units.USD) AS f
    UNION ALL
    SELECT '0001874178' AS cik, 'net_income' AS metric, tag AS concept, CAST(f.fy AS INT) AS fiscal_year,
           f.fp AS fiscal_period, f.`start` AS period_start, COALESCE(f.`end`, '') AS period_end,
