           f.fp AS fiscal_period, CAST(NULL AS STRING) AS period_start, COALESCE(f.`end`, '') AS period_end,
           CAST(f.val AS DOUBLE) AS value_usd, f.form AS form, f.filed AS filed, f.accn AS accession
    FROM sec_data.rivian_long_term_debt_raw LATERAL VIEW explode(units.USD) AS f
    UNION ALL
    SELECT '0001811210' AS cik, 'revenue' AS metric, tag AS concept, CAST(f.fy AS INT) AS fiscal_year,
           f.fp AS fiscal_period, f.`start` AS period_start, COALESCE(f.`end`, '') AS period_end,
           CAST(f.val AS DOUBLE) AS value_usd, f.form AS form, f.filed AS filed, f.accn AS accession
    FROM sec_data.lucid_revenue_raw LATERAL VIEW explode(units.USD) AS f
    UNION ALL
    SELECT '0001811210' AS cik, 'net_income' AS metric, tag AS concept, CAST(f.fy AS INT) AS fiscal_year,
           f.fp AS fiscal_period, f.`start` AS period_start, COALESCE(f.`end`, '') AS period_end,
           CAST(f.val AS DOUBLE) AS value_usd, f.form AS form, f.filed AS filed, f.accn AS accession
    FROM sec_data.lucid_net_income_raw LATERAL VIEW explode(units.USD) AS f
    UNION ALL
    SELECT '0001811210' AS cik, 'cash' AS metric, tag AS concept, CAST(f.fy AS INT) AS fiscal_year,
           f.fp AS fiscal_period, CAST(NULL AS STRING) AS period_start, COALESCE(f.`end`, '') AS period_end,
           CAST(f.val AS DOUBLE) AS value_usd, f.form AS form, f.filed AS filed, f.accn AS accession
    FROM sec_data.lucid_cash_raw LATERAL VIEW explode(units.USD) AS f
    UNION ALL
    SELECT '0001811210' AS cik, 'operating_cash_flow' AS metric, tag AS concept, CAST(f.fy AS INT) AS fiscal_year,
           f.fp AS fiscal_period, f.`start` AS period_start, COALESCE(f.`end`, '') AS period_end,
           CAST(f.val AS DOUBLE) AS value_usd, f.form AS form, f.filed AS filed, f.accn AS accession
    FROM sec_data.lucid_operating_cash_flow_raw LATERAL VIEW explode(units.USD) AS f
    UNION ALL
    SELECT '0001811210' AS cik, 'long_term_debt' AS metric, tag AS concept, CAST(f.fy AS INT) AS fiscal_year,
           f.fp AS fiscal_period, CAST(NULL AS STRING) AS period_start, COALESCE(f.`end`, '') AS period_end,
           CAST(f.val AS DOUBLE) AS value_usd, f.form AS form, f.filed AS filed, f.accn AS accession
    FROM sec_data.lucid_long_term_debt_raw LATERAL VIEW explode(units.USD) AS f
) AS facts
;

REGISTER DQ valid_reported_fact TABLE lightning.metastore.dd.dd_usl.financial_fact AS
value_usd IS NOT NULL AND form IS NOT NULL AND (period_start IS NULL OR period_end >= period_start)
;
